<script setup>import{computed}from'vue';import{Head,Link,router}from'@inertiajs/vue3';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';const p=defineProps({host:Object,results:Array,incidents:Array,uptime:Number,range:String});const points=computed(()=>{if(!p.results.length)return'';const vals=p.results.map(x=>x.latency_ms||0),max=Math.max(...vals,1);return vals.map((v,i)=>((i/(vals.length-1||1))*100)+','+(42-(v/max)*36)).join(' ')});const selectRange=x=>router.get(route('hosts.show',p.host.id),{range:x},{preserveState:true});</script>
<template><Head :title="host.name"/><AuthenticatedLayout><template #header><div><div class="flex items-center gap-3"><h1 class="text-lg font-semibold text-white">{{host.name}}</h1><span :class="'status-'+({active:'emerald',down:'red',unstable:'amber',unknown:'slate'}[host.current_status])" class="status-pill"><i></i>{{host.current_status}}</span></div><p class="font-mono text-xs text-slate-500">{{host.ip_address}}</p></div></template><div class="grid gap-4 md:grid-cols-4"><div class="metric"><b>{{host.current_latency??'—'}}</b><span>Latency ms</span></div><div class="metric"><b>{{host.packet_loss??'—'}}%</b><span>Packet loss</span></div><div class="metric"><b>{{uptime===null?'—':uptime+'%'}}</b><span>Uptime</span></div><div class="metric"><b>{{host.last_checked_at?new Date(host.last_checked_at).toLocaleTimeString():'—'}}</b><span>Last check</span></div></div><div class="mt-5 rounded-xl border border-slate-800 bg-slate-900 p-5"><div class="flex justify-between"><h2 class="font-semibold text-white">Latency history</h2><div class="space-x-1"><button v-for="x in ['1h','6h','24h','7d','30d']" @click="selectRange(x)" :class="p.range===x?'bg-emerald-500 text-slate-950':'bg-slate-800'" class="rounded px-2 py-1 text-xs">{{x}}</button></div></div><svg viewBox="0 0 100 46" preserveAspectRatio="none" class="mt-5 h-56 w-full"><line x1="0" y1="42" x2="100" y2="42" stroke="#334155" stroke-width=".3"/><polyline v-if="points" :points="points" fill="none" stroke="#34d399" stroke-width="1" vector-effect="non-scaling-stroke"/></svg></div><div class="mt-5 overflow-hidden rounded-xl border border-slate-800 bg-slate-900"><h2 class="border-b border-slate-800 p-5 font-semibold text-white">Recent incidents</h2><div v-for="i in incidents" class="flex justify-between border-b border-slate-800 p-4 text-sm"><span><b class="text-red-400">{{i.status.toUpperCase()}}</b> · {{i.reason}}</span><span class="text-slate-500">{{new Date(i.started_at).toLocaleString()}} · {{i.duration_seconds?Math.round(i.duration_seconds/60)+' min':'ongoing'}}</span></div><div v-if="!incidents.length" class="p-8 text-center text-slate-500">No downtime incidents.</div></div></AuthenticatedLayout></template>
